215	export function useTimeTrackerStorage<T>(read: (scope?: AccountScope) => T, write: (value: T, scope?: AccountScope) => void): readonly [T, (next: T | ((prev: T) => T)) => void] {
216	  const scope = useRef(accountScope.capture()).current;
217	  const [value, setValue] = useState<T>(() => read(scope));
218	  const valueRef = useRef(value);
219	
220	  useEffect(() => {
221	    valueRef.current = value;
222	  }, [value]);
223	
224	  useEffect(() => {
225	    function refresh(): void {
226	      if (!accountScope.isReady(scope)) return;
227	      const nextValue = read(scope);
228	      valueRef.current = nextValue;
229	      setValue(nextValue);
230	    }
231	    window.addEventListener("storage", refresh);
232	    window.addEventListener(TIME_TRACKER_STORAGE_EVENT, refresh);
233	    return () => {
234	      window.removeEventListener("storage", refresh);
235	      window.removeEventListener(TIME_TRACKER_STORAGE_EVENT, refresh);
236	    };
237	  }, [read, scope]);
238	
239	  const setStored = useCallback(
240	    (next: T | ((prev: T) => T)) => {
241	      if (!accountScope.isReady(scope)) return;
242	      const nextValue = typeof next === "function" ? (next as (prev: T) => T)(valueRef.current) : next;
243	      valueRef.current = nextValue;
244	      write(nextValue, scope);
245	      setValue(nextValue);
246	    },
247	    [write, scope],
248	  );
249	
250	  return [value, setStored] as const;
251	}
