257	export function sessionInvariantError(entry: TimeTrackerEntry): string | null {
258	  if (entry.segments.some(segment => !Number.isFinite(segment.start) || (segment.end !== null && (!Number.isFinite(segment.end) || segment.end < segment.start)))) return "Invalid interval ordering";
259	  let previousEnd = -Infinity;
260	  for (const [index, segment] of entry.segments.entries()) {
261	    if (segment.start < previousEnd) return "Overlapping intervals";
262	    if (segment.end === null && (entry.done || index !== entry.segments.length - 1)) return "Invalid open interval";
263	    previousEnd = segment.end ?? Infinity;
264	  }
265	  return null;
266	}
