268	type EntryUpdate = TimeTrackerEntry[] | ((prev: TimeTrackerEntry[]) => TimeTrackerEntry[]);
269	
270	/** All interactive entry mutations use this account-scoped lock. Expected source
271	 * is captured when the command is submitted, never after waiting for the lock. */
272	export async function commitTimeTrackerEntries(
273	  next: EntryUpdate,
274	  expected: readonly TimeTrackerEntry[],
275	  scope: AccountScope,
276	): Promise<TimeTrackerEntry[]> {
277	  accountScope.assertCurrent(scope);
278	  if (typeof navigator === "undefined" || !navigator.locks?.request) throw new Error("Safe timer writes require Web Locks. Use a supported browser; existing data was preserved.");
279	  const physical = accountScope.physicalKey(TIME_TRACKER_ENTRIES_KEY, scope);
280	  return navigator.locks.request(`xai-tt:${physical}`, () => {
281	    accountScope.assertCurrent(scope);
282	    const raw = localStorage.getItem(physical);
283	    const parsed = raw === null ? [] : safeParse(raw);
284	    if (!Array.isArray(parsed) || !parsed.every(isEntry) || parsed.some(entry => sessionInvariantError(entry))) {
285	      throw new Error("Stored sessions need recovery. Original data was preserved; export it before repairing intervals.");
286	    }
287	    const current = parsed.filter(entry => entry.deleted !== true);
288	    if (JSON.stringify(current) !== JSON.stringify(expected)) throw new Error("Sessions changed in another tab. Review the latest data before trying again.");
289	    const updated = typeof next === "function" ? next(current) : next;
290	    if (updated.some(entry => !isEntry(entry) || sessionInvariantError(entry))) throw new Error("The proposed session has invalid intervals. Original data was preserved.");
291	    const active = updated.filter(isRunningEntry);
292	    if (readTimeTrackerMode() === "single" && active.length > 1 && active.some(entry => !current.some(old => old.id === entry.id && isRunningEntry(old)))) {
293	      throw new Error("Single-task mode already has a running session. End it before starting or resuming another.");
294	    }
295	    if (JSON.stringify(updated) !== JSON.stringify(current)) writeTimeTrackerEntries([...parsed.filter(entry => entry.deleted === true), ...updated], scope);
296	    return updated;
297	  });
298	}
299	
300	export function useTimeTrackerEntries() {
301	  const scope = useRef(accountScope.capture()).current;
302	  const [entries, setEntries] = useState(() => readTimeTrackerEntries(scope));
303	  const value = useRef(entries);
304	  const [error, setError] = useState<string | null>(null);
305	  useEffect(() => {
306	    const refresh = () => {
307	      if (!accountScope.isReady(scope)) return;
308	      try { value.current = readTimeTrackerEntries(scope); setEntries(value.current); }
309	      catch { setError("Session storage could not be read. Existing data was preserved."); }
310	    };
311	    window.addEventListener("storage", refresh);
312	    window.addEventListener(TIME_TRACKER_STORAGE_EVENT, refresh);
313	    return () => { window.removeEventListener("storage", refresh); window.removeEventListener(TIME_TRACKER_STORAGE_EVENT, refresh); };
314	  }, [scope]);
315	  const commit = useCallback(async (next: EntryUpdate): Promise<boolean> => {
316	    const expected = value.current;
317	    try {
318	      await commitTimeTrackerEntries(next, expected, scope);
319	      accountScope.assertCurrent(scope);
320	      value.current = readTimeTrackerEntries(scope); setEntries(value.current); setError(null); return true;
321	    } catch (cause) { setError(cause instanceof Error ? cause.message : "Session could not be saved."); return false; }
322	  }, [scope]);
323	  const exportSource = () => {
324	    accountScope.assertCurrent(scope);
325	    return localStorage.getItem(accountScope.physicalKey(TIME_TRACKER_ENTRIES_KEY, scope)) ?? "[]";
326	  };
327	  return [entries, commit, { error, exportSource }] as const;
328	}
329	
330	export function useTimeTrackerMode(): readonly [TimeTrackerMode, (next: TimeTrackerMode | ((prev: TimeTrackerMode) => TimeTrackerMode)) => void] {
331	  const read = useCallback(readTimeTrackerMode, []);
332	  const write = useCallback(writeTimeTrackerMode, []);
333	  return useTimeTrackerStorage(read, write);
334	}
335	
336	export function useCategoryMap(categories: readonly TimeTrackerCategory[]): ReadonlyMap<string, TimeTrackerCategory> {
337	  return useMemo(() => new Map(categories.map((category) => [category.id, category])), [categories]);
338	}
339	
340	registerAccountMigrationValidator(TIME_TRACKER_CATEGORIES_KEY, value => Array.isArray(value) && value.every(isCategory));
341	registerAccountMigrationValidator(TIME_TRACKER_ENTRIES_KEY, value => Array.isArray(value) && value.every(isEntry));
